{
 "summary": "The theorem proves that in any finite group with zero K, every nonzero a satisfies a^(|K|-1) = 1. Every finite field is a finite group with zero, so this generalizes the paper's finite-field statement. The only caveat is that the Lean statement is stronger than the paper, which is acceptable. The natural-number subtraction is safe because a GroupWithZero is nontrivial, so |K| ≥ 2.",
 "glossary": [
  {"decl": "Fintype.card K", "line": 5, "plain": "q = |K|, the number of elements of K", "standard_concept": "cardinality of a finite set", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "stmt", "line": 5, "plain": "For any finite type K carrying a GroupWithZero structure (a monoid with 0 ≠ 1 in which every nonzero element is invertible) and any a ∈ K with a ≠ 0, we have a^(|K|-1) = 1."}
 ],
 "paper_claims": [
  {"ref": "Theorem (Fermat's little theorem, finite-field form)", "plain": "If K is a finite field with q elements, then a^(q-1) = 1 for every nonzero a ∈ K."}
 ],
 "coverage": [
  {"paper_ref": "Theorem (Fermat's little theorem, finite-field form)", "lean_theorem": "stmt", "relation": "lean_stronger", "why": "Every finite field is a finite GroupWithZero, and the Lean statement does not require commutativity or addition."}
 ],
